import math

M = 2004
required_sets = 2 * M # Assuming all 2M sets must be distinct

def combinations(n, k):
    if k < 0 or k > n:
        return 0
    return math.comb(n, k)

# Test small values of k to find the minimum required n
k_values = range(1, 8)
results = {}

for k in k_values:
    n = 1
    while combinations(n, k) < required_sets:
        n += 1
    results[k] = n

print(f"Required sets: {required_sets}")
for k, n in results.items():
    print(f"For fixed size k={k}, the minimum required n is {n}.")

